create table audit_logs (created_at timestamp(6), entity_id bigint, id bigserial not null, user_id bigint, result varchar(16), ip_address varchar(64), action varchar(255) not null, entity_type varchar(255), module varchar(255) not null, new_value TEXT, old_value TEXT, user_email varchar(255), primary key (id));
create table barns (capacity integer, created_at timestamp(6), farm_id bigint not null, id bigserial not null, updated_at timestamp(6), barn_type varchar(255), name varchar(255) not null, status varchar(255), primary key (id));
create table biosecurity_logs (footbath_completed boolean not null, ppe_check_completed boolean not null, vehicle_spray_completed boolean not null, visitor_log_completed boolean not null, created_at timestamp(6), farm_id bigint, flock_id bigint, id bigserial not null, logged_by bigint, visit_timestamp timestamp(6), barn_id varchar(255), notes TEXT, staff_signature varchar(255), primary key (id));
create table biosecurity_protocols (footbath_refreshed boolean not null, ppe_worn boolean not null, vehicular_spray boolean not null, visitor_logged boolean not null, farm_id bigint not null, id bigserial not null, timestamp timestamp(6), notes varchar(255), staff_signature varchar(255), vehicle_reg varchar(255), visitor_name varchar(255), primary key (id));
create table cash_reconciliations (actual_cash numeric(38,2) not null, expected_cash numeric(38,2) not null, reconciliation_date date not null, variance numeric(38,2) not null, closed_by bigint, created_at timestamp(6), id bigserial not null, notes TEXT, status varchar(255) not null, primary key (id));
create table chart_of_accounts (balance numeric(38,2) not null, is_header boolean not null, id bigserial not null, parent_id bigint, account_code varchar(255) not null unique, account_name varchar(255) not null, account_type varchar(255) not null check (account_type in ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')), business_unit varchar(255) check (business_unit in ('POULTRY_FARM','PHARMACY','CONSULTING','TRAINING','GENERAL')), description varchar(255), primary key (id));
create table chicken_delivery_releases (authorized_chicken_quantity integer not null, bonus_quantity integer not null, dispatch_date date, payment_amount numeric(14,2), stock_decremented boolean not null, chicken_sale_id bigint not null, chicken_sale_payment_id bigint, created_at timestamp(6), created_by bigint, customer_id bigint, dispatched_at timestamp(6), dispatched_by bigint, farm_approved_at timestamp(6), farm_approved_by bigint, farm_id bigint, flock_id bigint, id bigserial not null, invoice_id bigint, updated_at timestamp(6), verified_at timestamp(6), verified_by bigint, version bigint, status varchar(30) not null check (status in ('SUBMITTED','UNDER_REVIEW','VERIFIED','REJECTED','FORWARDED_TO_FARM','FARM_PENDING','FARM_APPROVED','FARM_REJECTED','DISPATCHED','MARKETING_RECEIVED','OUT_FOR_DELIVERY','DELIVERED','DELIVERY_FAILED','CANCELLED')), release_number varchar(40) not null unique, chicken_type varchar(80), delivery_outcome varchar(120), payment_receipt_url varchar(500), farm_rejection_reason TEXT, marketing_notes TEXT, notes TEXT, primary key (id));
create table chicken_sale_items (line_subtotal numeric(14,2) not null, price_per_kg numeric(14,2), quantity integer not null, unit_price numeric(14,2), weight_kg numeric(14,3), flock_id bigint not null, id bigserial not null, sale_id bigint not null, notes TEXT, pricing_method varchar(255) not null check (pricing_method in ('PER_BIRD','BY_WEIGHT')), primary key (id));
create table chicken_sale_payments (amount numeric(14,2) not null, payment_date date not null, created_at timestamp(6), finance_transaction_id bigint, id bigserial not null, invoice_id bigint, recorded_by bigint, sale_id bigint not null, notes TEXT, payment_method varchar(255) not null check (payment_method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), primary key (id));
create table chicken_sales (discount_amount numeric(14,2) not null, outstanding_amount numeric(14,2) not null, paid_amount numeric(14,2) not null, sale_date date not null, subtotal numeric(14,2) not null, tax_amount numeric(14,2) not null, total_amount numeric(14,2) not null, barn_id bigint, confirmed_by bigint, created_at timestamp(6), created_by bigint, customer_id bigint not null, farm_id bigint not null, flock_id bigint not null, id bigserial not null, invoice_id bigint, updated_at timestamp(6), version bigint, notes TEXT, sale_number varchar(255) not null unique, sale_type varchar(255) not null check (sale_type in ('RETAIL','WHOLESALE','B2B','FARM_GATE')), status varchar(255) not null check (status in ('DRAFT','CONFIRMED','INVOICED','PARTIALLY_PAID','PAID','COMPLETED','CANCELLED')), primary key (id));
create table consultancy_activities (activity_date date not null, duration_minutes integer, end_time time(6), start_time time(6), consultant_id bigint, created_at timestamp(6), created_by bigint, customer_id bigint not null, engagement_id bigint not null, id bigserial not null, updated_at timestamp(6), activity_number varchar(40) not null, activity_type varchar(255) not null check (activity_type in ('SITE_VISIT','FARM_INSPECTION','CLIENT_MEETING','ASSESSMENT','ADVISORY_SESSION','FOLLOW_UP','REPORT_PREPARATION','REMOTE_CONSULTATION','OTHER')), customer_notes TEXT, description TEXT not null, findings TEXT, location varchar(255), recommendations TEXT, status varchar(255) not null check (status in ('PLANNED','IN_PROGRESS','COMPLETED','CANCELLED')), primary key (id), constraint uk_consultancy_activity_number unique (activity_number));
create table consultancy_assignments (assigned_date date, end_date date, start_date date, assigned_by bigint, consultant_user_id bigint not null, created_at timestamp(6), engagement_id bigint not null, id bigserial not null, updated_at timestamp(6), notes TEXT, role varchar(255) not null check (role in ('LEAD_CONSULTANT','SUPPORT_CONSULTANT','PROJECT_COORDINATOR','SPECIALIST')), status varchar(255) not null check (status in ('ASSIGNED','ACTIVE','REMOVED','COMPLETED')), primary key (id), constraint uk_consultancy_assignment_engagement_user unique (engagement_id, consultant_user_id));
create table consultancy_contracts (contract_value numeric(14,2) not null, end_date date, signed_date date, start_date date, created_at timestamp(6), created_by bigint, currency varchar(8) not null, customer_id bigint not null, engagement_id bigint not null unique, id bigserial not null, updated_at timestamp(6), contract_number varchar(40) not null, notes TEXT, scope TEXT, status varchar(255) not null check (status in ('DRAFT','PENDING_SIGNATURE','ACTIVE','EXPIRED','TERMINATED','COMPLETED','CANCELLED')), terms TEXT, title varchar(255) not null, primary key (id), constraint uk_consultancy_contract_number unique (contract_number));
create table consultancy_deliverables (approved_date date, billable boolean not null, billable_amount numeric(14,2), due_date date, submitted_date date, assigned_to bigint, created_at timestamp(6), created_by bigint, engagement_id bigint not null, id bigserial not null, invoice_id bigint, updated_at timestamp(6), deliverable_number varchar(40) not null, description TEXT, notes TEXT, rejection_reason TEXT, status varchar(255) not null check (status in ('PENDING','IN_PROGRESS','SUBMITTED','APPROVED','REJECTED','CANCELLED')), title varchar(255) not null, primary key (id), constraint uk_consultancy_deliverable_number unique (deliverable_number));
create table consultancy_engagements (actual_end_date date, agreed_amount numeric(14,2) not null, estimated_amount numeric(14,2), expected_end_date date, invoiced_amount numeric(14,2) not null, outstanding_amount numeric(14,2) not null, paid_amount numeric(14,2) not null, start_date date, completed_at timestamp(6), completed_by bigint, created_at timestamp(6), created_by bigint, currency varchar(8) not null, customer_id bigint not null, id bigserial not null, invoice_id bigint, lead_consultant_id bigint, proposal_id bigint, request_id bigint, service_id bigint, updated_at timestamp(6), engagement_number varchar(40) not null, billing_type varchar(255) not null check (billing_type in ('FIXED_PRICE','TIME_AND_MATERIAL','MILESTONE','RETAINER')), completion_notes TEXT, description TEXT, location varchar(255), notes TEXT, objectives TEXT, payment_status varchar(255) not null check (payment_status in ('UNPAID','PARTIALLY_PAID','PAID')), priority varchar(255) not null check (priority in ('LOW','MEDIUM','HIGH','URGENT')), scope TEXT, status varchar(255) not null check (status in ('DRAFT','PROPOSED','APPROVED','ACTIVE','ON_HOLD','COMPLETED','CANCELLED')), title varchar(255) not null, primary key (id), constraint uk_consultancy_engagement_number unique (engagement_number), constraint uk_consultancy_engagement_request unique (request_id));
create table consultancy_payments (amount numeric(14,2) not null, payment_date date, created_at timestamp(6), currency varchar(8) not null, engagement_id bigint not null, id bigserial not null, invoice_id bigint, recorded_by bigint, payment_number varchar(40) not null, method varchar(255), notes TEXT, reference varchar(255), primary key (id), constraint uk_consultancy_payment_number unique (payment_number));
create table consultancy_proposals (proposed_amount numeric(14,2) not null, valid_until date, converted_engagement_id bigint, created_at timestamp(6), created_by bigint, currency varchar(8) not null, customer_id bigint not null, id bigserial not null, request_id bigint, service_id bigint, updated_at timestamp(6), proposal_number varchar(40) not null, notes TEXT, scope TEXT, status varchar(255) not null check (status in ('DRAFT','SENT','ACCEPTED','REJECTED','EXPIRED','CANCELLED')), title varchar(255) not null, primary key (id), constraint uk_consultancy_proposal_number unique (proposal_number));
create table consultancy_requests (requested_date date, assigned_consultant_id bigint, created_at timestamp(6), created_by bigint, crm_quotation_id bigint, customer_id bigint not null, id bigserial not null, service_id bigint, updated_at timestamp(6), request_number varchar(40) not null, description TEXT, notes TEXT, preferred_location varchar(255), priority varchar(255) not null check (priority in ('LOW','MEDIUM','HIGH','URGENT')), status varchar(255) not null check (status in ('NEW','QUALIFYING','ASSIGNED','PROPOSAL_REQUIRED','CONVERTED','REJECTED','CANCELLED')), subject varchar(255) not null, primary key (id), constraint uk_consultancy_request_number unique (request_number), constraint uk_consultancy_request_crm_quotation unique (crm_quotation_id));
create table consultancy_services (active boolean not null, default_duration_days integer, default_price numeric(14,2) not null, tax_applicable boolean not null, created_at timestamp(6), created_by bigint, currency varchar(8) not null, id bigserial not null, updated_at timestamp(6), service_code varchar(40) not null, category varchar(255) not null check (category in ('FARM_ASSESSMENT','POULTRY_SETUP','LIVESTOCK','FEED_NUTRITION','BIOSECURITY','FARM_MANAGEMENT','PRODUCTIVITY','ONSITE_ADVISORY','BUSINESS_ADVISORY','OTHER')), description TEXT, name varchar(255) not null, primary key (id), constraint uk_consultancy_service_code unique (service_code));
create table crm_activities (activity_date timestamp(6), client_id bigint, created_at timestamp(6), id bigserial not null, lead_id bigint, opportunity_id bigint, performed_by bigint, type varchar(20) not null check (type in ('CALL','MEETING','EMAIL','VISIT','NOTE','FOLLOW_UP')), body TEXT, subject varchar(255) not null, primary key (id));
create table crm_clients (number_of_chickens integer, assigned_extension_worker_id bigint, assigned_owner_id bigint, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), customer_type varchar(30) check (customer_type in ('INDIVIDUAL','COMPANY','ORGANIZATION','FARM')), customer_code varchar(40), tax_identifier varchar(80), address varchar(255), city varchar(255), client_name varchar(255) not null, contact_person varchar(255), email varchar(255), farm_size varchar(255), farm_type varchar(255), location varchar(255), notes TEXT, phone varchar(255), region varchar(255), status varchar(255) check (status in ('LEAD','ACTIVE','INACTIVE','LOST')), primary key (id), constraint uk_crm_client_customer_code unique (customer_code));
create table crm_leads (assigned_owner_id bigint, converted_at timestamp(6), converted_by bigint, converted_client_id bigint, converted_opportunity_id bigint, created_at timestamp(6), id bigserial not null, marketing_lead_id bigint, updated_at timestamp(6), priority varchar(20) check (priority in ('LOW','MEDIUM','HIGH','URGENT')), status varchar(20) not null check (status in ('NEW','CONTACTED','QUALIFIED','UNQUALIFIED','CONVERTED','LOST')), source varchar(30) check (source in ('WEBSITE','REFERRAL','SOCIAL_MEDIA','EVENT','TRAINING','CONSULTANCY','FARM_SERVICE','PHARMACY','MARKETING','OTHER')), lead_number varchar(40) not null, company varchar(255), contact_person varchar(255), email varchar(255), industry varchar(255), name varchar(255) not null, notes TEXT, phone varchar(255), primary key (id), constraint uk_crm_lead_number unique (lead_number));
create table crm_number_sequences (next_value bigint not null, name varchar(40) not null, primary key (name));
create table crm_opportunities (estimated_value numeric(14,2), expected_close_date date, probability integer, client_id bigint not null, created_at timestamp(6), currency varchar(8), id bigserial not null, lead_id bigint, sales_owner_id bigint, updated_at timestamp(6), priority varchar(20) check (priority in ('LOW','MEDIUM','HIGH','URGENT')), source varchar(30) check (source in ('WEBSITE','REFERRAL','SOCIAL_MEDIA','EVENT','TRAINING','CONSULTANCY','FARM_SERVICE','PHARMACY','MARKETING','OTHER')), stage varchar(30) not null check (stage in ('PROSPECTING','QUALIFICATION','PROPOSAL','NEGOTIATION','WON','LOST')), opportunity_number varchar(40) not null, description TEXT, loss_reason varchar(255), notes TEXT, title varchar(255) not null, primary key (id), constraint uk_crm_opportunity_number unique (opportunity_number));
create table crm_order_payments (amount numeric(14,2) not null, payment_date date, created_at timestamp(6), finance_transaction_id bigint, id bigserial not null, invoice_id bigint, order_id bigint not null, recorded_by bigint, method varchar(30) check (method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), payment_number varchar(40) not null, idempotency_key varchar(80), primary key (id), constraint uk_crm_order_payment_number unique (payment_number), constraint uk_crm_order_payment_idempotency unique (idempotency_key));
create table crm_quotation_items (discount_amount numeric(14,2), line_total numeric(14,2), quantity float(53) not null, tax_amount numeric(14,2), unit_price numeric(14,2) not null, id bigserial not null, quotation_id bigint not null, description varchar(255) not null, product_or_service varchar(255), unit varchar(255), primary key (id));
create table crm_quotations (discount_amount numeric(14,2), expiry_date date, issue_date date, subtotal numeric(14,2), tax_amount numeric(14,2), total_amount numeric(14,2), approved_by bigint, client_id bigint not null, consultancy_contract_id bigint, consultancy_engagement_id bigint, consultancy_request_id bigint, converted_order_id bigint, created_at timestamp(6), created_by bigint, currency varchar(8), id bigserial not null, opportunity_id bigint, updated_at timestamp(6), quotation_type varchar(20) check (quotation_type in ('PRODUCT','SERVICE','CONSULTANCY')), status varchar(20) not null check (status in ('DRAFT','SUBMITTED','APPROVED','SENT','ACCEPTED','REJECTED','EXPIRED','CANCELLED')), quotation_number varchar(40) not null, notes TEXT, primary key (id), constraint uk_crm_quotation_number unique (quotation_number));
create table crm_tasks (due_date date, assigned_user_id bigint, client_id bigint, completed_at timestamp(6), created_at timestamp(6), id bigserial not null, lead_id bigint, opportunity_id bigint, updated_at timestamp(6), priority varchar(20) check (priority in ('LOW','MEDIUM','HIGH','URGENT')), status varchar(20) not null check (status in ('TODO','IN_PROGRESS','COMPLETED','CANCELLED')), description TEXT, title varchar(255) not null, primary key (id));
create table customer_order_items (quantity float(53), subtotal numeric(38,2), unit_price numeric(38,2), flock_id bigint, id bigserial not null, order_id bigint not null, category varchar(255), product_name varchar(255) not null, unit varchar(255), primary key (id));
create table customer_orders (discount_amount numeric(14,2), expected_delivery_date date, order_date date, paid_amount numeric(14,2), subtotal numeric(14,2), tax_amount numeric(14,2), total_amount numeric(14,2), client_id bigint not null, created_at timestamp(6), created_by bigint, currency varchar(8), id bigserial not null, invoice_id bigint, opportunity_id bigint, quotation_id bigint, updated_at timestamp(6), order_number varchar(40), status varchar(40), contact_number varchar(255), delivery_address varchar(255), notes TEXT, primary key (id), constraint uk_customer_order_number unique (order_number), constraint uk_customer_order_quotation unique (quotation_id));
create table customer_wallets (balance numeric(38,2) not null, credit_limit numeric(38,2) not null, is_blocked boolean not null, client_id bigint not null unique, id bigserial not null, client_name varchar(255), primary key (id));
create table daily_farm_records (average_weight numeric(38,2), culled_chickens integer, date date not null, feed_consumed numeric(38,2), mortality integer, opening_bird_count integer, water_consumed numeric(38,2), created_at timestamp(6), disease_case_id bigint, farm_id bigint not null, flock_id bigint not null, id bigserial not null, recorded_by bigint, silo_id bigint, updated_at timestamp(6), barn_photo_url varchar(255), mortality_cause varchar(255) check (mortality_cause in ('DISEASE','PREDATOR','HEAT','CULLING','UNKNOWN')), mortality_notes TEXT, symptoms_or_remarks varchar(255), primary key (id), unique (farm_id, flock_id, date));
create table daily_feed_usage_lines (consumed_quantity numeric(14,3), issued_quantity numeric(14,3), returned_quantity numeric(14,3), daily_record_id bigint not null, id bigserial not null, inventory_item_id bigint, stock_movement_id bigint, unit varchar(20), feed_type varchar(40), notes TEXT, primary key (id));
create table daily_medication_lines (inventory_already_posted boolean not null, quantity numeric(14,3), daily_record_id bigint not null, id bigserial not null, inventory_item_id bigint, stock_movement_id bigint, unit varchar(20), treatment_type varchar(40) not null, notes TEXT, primary key (id));
create table daily_mortality_lines (death_count integer not null, daily_record_id bigint not null, id bigserial not null, cause varchar(255) check (cause in ('DISEASE','PREDATOR','HEAT','CULLING','UNKNOWN')), notes TEXT, primary key (id));
create table delivery_schedules (scheduled_date date, created_at timestamp(6), id bigserial not null, order_id bigint not null unique, driver_name varchar(255), route_name varchar(255), status varchar(255), vehicle_plate varchar(255), primary key (id));
create table demand_forecasts (actual_demand float(53), confidence_score float(53), forecast_date date not null, predicted_demand float(53), created_at timestamp(6), id bigserial not null, inventory_item_id bigint not null, algorithm_used varchar(255), forecast_period varchar(255) not null, primary key (id));
create table disease_cases (date_detected date, date_resolved date, number_affected integer, number_dead integer, created_at timestamp(6), farm_id bigint, flock_id bigint, id bigserial not null, reported_by bigint, updated_at timestamp(6), vet_assigned bigint, action_taken TEXT, attachment_path varchar(255), barn_id varchar(255), diagnosis varchar(255), disease_type varchar(255), severity varchar(255) check (severity in ('LOW','MODERATE','HIGH','CRITICAL')), status varchar(255) check (status in ('ACTIVE','CONTROLLED','RESOLVED')), suspected_disease varchar(255), symptoms TEXT, primary key (id));
create table document_templates (active boolean not null, version integer not null, id bigserial not null, updated_at timestamp(6), module varchar(40), code varchar(60) not null unique, name varchar(120) not null, primary key (id));
create table dur_alerts (resolved boolean, created_at timestamp(6), id bigserial not null, prescription_id bigint, sale_id bigint, severity varchar(10), alert_type varchar(50), message TEXT not null, primary key (id));
create table environment_records (ammoniappm float(53), co2ppm float(53), humidity float(53), lighting_hours float(53), temperature float(53), barn_id bigint not null, created_at timestamp(6), id bigserial not null, timestamp timestamp(6), data_source varchar(255), primary key (id));
create table farm_cost_allocations (amount numeric(38,2) not null, transaction_date date, created_at timestamp(6), farm_id bigint not null, flock_id bigint, id bigserial not null, reference_id bigint, cost_type varchar(255) not null check (cost_type in ('FEED','DRUG','VACCINE','LABOR','TRANSPORT','OTHER')), reference_type varchar(255), primary key (id));
create table farm_number_sequences (next_value bigint not null, name varchar(40) not null, primary key (name));
create table farm_visits (next_follow_up_date date, visit_date date, client_id bigint not null, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), visited_by bigint, advice_given TEXT, observation TEXT, purpose varchar(255), primary key (id));
create table farms (capacity integer, assigned_farm_manager_id bigint, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), farm_name varchar(255) not null, farm_type varchar(255) check (farm_type in ('BROILER','LAYER','MIXED')), location varchar(255), status varchar(255) check (status in ('ACTIVE','INACTIVE')), primary key (id));
create table feed_deliveries (delivery_date date, quantity float(53), unit_cost float(53), created_at timestamp(6), id bigserial not null, silo_id bigint not null, batch_number varchar(255), supplier varchar(255), primary key (id));
create table feed_recipe_ingredients (percentage float(53), id bigserial not null, recipe_id bigint not null, ingredient_name varchar(255) not null, primary key (id));
create table feed_recipes (cost_per_kg float(53), energy_kcal float(53), protein_percentage float(53), created_at timestamp(6), id bigserial not null, updated_at timestamp(6), growth_stage varchar(255), name varchar(255) not null, primary key (id));
create table finance_audit_logs (amount numeric(19,4) not null, id bigserial not null, performed_by bigint, posted_at timestamp(6) not null, reference_id bigint, transaction_id bigint not null, action varchar(512) not null, credit_account varchar(255) not null, debit_account varchar(255) not null, reference_type varchar(255), source_module varchar(255) not null, primary key (id));
create table finance_transactions (amount numeric(38,2) not null, transaction_date date, vat_amount numeric(38,2), created_at timestamp(6), credit_account_id bigint, debit_account_id bigint, id bigserial not null, recorded_by bigint, reference_id bigint, business_unit varchar(255) check (business_unit in ('POULTRY_FARM','PHARMACY','CONSULTING','TRAINING','GENERAL')), category varchar(255), description TEXT, invoice_ref varchar(255), payment_method varchar(255) check (payment_method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), reference_type varchar(255), source_module varchar(255), status varchar(255), transaction_type varchar(255) not null check (transaction_type in ('INCOME','EXPENSE','TRANSFER')), primary key (id), constraint uk_finance_tx_source_ref unique (source_module, reference_type, reference_id));
create table flock_observations (feed_intake_drop_percentage float(53), mortality_count integer, observation_date date, respiratory_distress_score integer, water_intake_drop_percentage float(53), created_at timestamp(6), flock_id bigint not null, id bigserial not null, observed_by bigint not null, diarrhea_type varchar(255), general_comments TEXT, primary key (id));
create table flock_population_events (event_date date not null, new_population integer not null, previous_population integer not null, quantity_change integer not null, chicken_sale_id bigint, created_at timestamp(6), flock_id bigint not null, id bigserial not null, recorded_by bigint, event_type varchar(255) not null check (event_type in ('SALE_CONFIRM','SALE_CANCEL_RESTORE','MORTALITY','DISPATCH','DISPATCH_BONUS','ADJUSTMENT')), notes TEXT, primary key (id));
create table flocks (current_bird_count integer, expected_end_date date, expected_harvest_date date, initial_bird_count integer, is_under_withdrawal boolean, start_date date, withdrawal_hold_until date, barn_id bigint, created_at timestamp(6), farm_id bigint not null, id bigserial not null, responsible_person_id bigint, supplier_id bigint, updated_at timestamp(6), version bigint, batch_code varchar(255) not null unique, bird_type varchar(255), breed varchar(255), notes TEXT, source_document_url varchar(255), source_hatchery varchar(255), status varchar(255) check (status in ('RECEIVED','ACTIVE','PARTIALLY_SOLD','CLOSED','CULLED','HARVESTED','SOLD')), primary key (id));
create table growth_records (average_weight float(53), breed_standard_weight float(53), sample_size integer, sampling_date date, uniformity float(53), created_at timestamp(6), flock_id bigint not null, id bigserial not null, primary key (id));
create table haccp_checklists (created_at timestamp(6), id bigserial not null, ccp_point varchar(255), corrective_action varchar(255), monitoring_frequency varchar(255), process_name varchar(255) not null, requirement varchar(255), primary key (id));
create table haccp_logs (is_compliant boolean, checked_by bigint, checklist_id bigint not null, id bigserial not null, timestamp timestamp(6), corrective_action_taken varchar(255), observation varchar(255), primary key (id));
create table health_issue_reports (mortality_observed integer, number_affected integer, report_date date, review_date date, created_at timestamp(6), daily_farm_record_id bigint, disease_case_id bigint, farm_id bigint not null, flock_id bigint not null, id bigserial not null, reported_by bigint, reviewed_by bigint, updated_at timestamp(6), remarks TEXT, severity varchar(255) check (severity in ('LOW','MODERATE','HIGH','CRITICAL')), status varchar(255) check (status in ('OPEN','REVIEWED','CLOSED')), suspected_diagnosis varchar(255), symptoms TEXT, treatment_plan TEXT, primary key (id));
create table hr_attendance (attendance_date date not null, check_in time(6), check_out time(6), hours_worked numeric(8,2) not null, created_at timestamp(6), employee_id bigint not null, id bigserial not null, recorded_by bigint, updated_at timestamp(6), notes TEXT, status varchar(255) not null check (status in ('PRESENT','ABSENT','LATE','HALF_DAY','ON_LEAVE','HOLIDAY','REST_DAY')), primary key (id), constraint uk_hr_attendance_employee_date unique (employee_id, attendance_date));
create table hr_departments (active boolean not null, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), code varchar(40) not null, description TEXT, name varchar(255) not null, primary key (id), constraint uk_hr_department_code unique (code));
create table hr_employees (basic_salary numeric(19,2) not null, hire_date date, termination_date date, created_at timestamp(6), currency varchar(8) not null, department_id bigint, id bigserial not null, manager_id bigint, position_id bigint, updated_at timestamp(6), user_id bigint, employee_number varchar(40) not null, address TEXT, bank_account_ref varchar(255), bank_name varchar(255), email varchar(255), emergency_contact varchar(255), employment_status varchar(255) not null check (employment_status in ('ACTIVE','ON_LEAVE','SUSPENDED','TERMINATED','RESIGNED','INACTIVE')), employment_type varchar(255) not null check (employment_type in ('FULL_TIME','PART_TIME','CONTRACT','TEMPORARY','INTERN')), first_name varchar(255) not null, last_name varchar(255) not null, middle_name varchar(255), notes TEXT, phone varchar(255), termination_reason TEXT, primary key (id), constraint uk_hr_employee_number unique (employee_number), constraint uk_hr_employee_user unique (user_id));
create table hr_leave_balances (balance_year integer not null, entitlement numeric(8,2) not null, remaining_days numeric(8,2) not null, used_days numeric(8,2) not null, created_at timestamp(6), employee_id bigint not null, id bigserial not null, leave_type_id bigint not null, updated_at timestamp(6), primary key (id), constraint uk_hr_leave_balance_employee_type_year unique (employee_id, leave_type_id, balance_year));
create table hr_leave_requests (end_date date not null, start_date date not null, total_days numeric(8,2) not null, approved_at timestamp(6), approved_by bigint, created_at timestamp(6), created_by bigint, employee_id bigint not null, id bigserial not null, leave_type_id bigint not null, updated_at timestamp(6), request_number varchar(40) not null, reason TEXT, rejection_reason TEXT, status varchar(255) not null check (status in ('PENDING','APPROVED','REJECTED','CANCELLED')), primary key (id), constraint uk_hr_leave_request_number unique (request_number));
create table hr_leave_types (active boolean not null, balance_controlled boolean not null, default_annual_entitlement numeric(8,2) not null, paid boolean not null, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), code varchar(40) not null, description TEXT, name varchar(255) not null, primary key (id), constraint uk_hr_leave_type_code unique (code));
create table hr_number_sequences (next_value bigint not null, name varchar(40) not null, primary key (name));
create table hr_payroll_deduction_types (active boolean not null, approved boolean default false not null, fixed_amount numeric(19,2), rate_percent numeric(8,4), created_at timestamp(6), id bigserial not null, updated_at timestamp(6), code varchar(40) not null, category varchar(255) not null check (category in ('INCOME_TAX','PENSION','OTHER')), name varchar(255) not null, notes TEXT, primary key (id), constraint uk_hr_deduction_type_code unique (code));
create table hr_payroll_items (allowances numeric(19,2) not null, basic_salary numeric(19,2) not null, bonuses numeric(19,2) not null, gross_salary numeric(19,2) not null, net_salary numeric(19,2) not null, other_deductions numeric(19,2) not null, overtime numeric(19,2) not null, paid_amount numeric(19,2) not null, pension numeric(19,2) not null, tax numeric(19,2) not null, total_deductions numeric(19,2) not null, created_at timestamp(6), currency varchar(8) not null, employee_id bigint not null, id bigserial not null, payroll_run_id bigint not null, updated_at timestamp(6), payment_status varchar(255) not null check (payment_status in ('PENDING','PARTIAL','PAID')), status varchar(255) not null check (status in ('CALCULATED','APPROVED','PROCESSED','PAID','CANCELLED')), primary key (id), constraint uk_hr_payroll_item_run_employee unique (payroll_run_id, employee_id));
create table hr_payroll_payments (amount numeric(19,2) not null, payment_date date not null, created_at timestamp(6), id bigserial not null, payroll_item_id bigint, payroll_run_id bigint not null, recorded_by bigint, payment_number varchar(40) not null, notes TEXT, payment_method varchar(255) not null check (payment_method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), primary key (id), constraint uk_hr_payroll_payment_number unique (payment_number));
create table hr_payroll_periods (end_date date not null, start_date date not null, approved_at timestamp(6), approved_by bigint, calculated_at timestamp(6), calculated_by bigint, closed_at timestamp(6), created_at timestamp(6), created_by bigint, id bigserial not null, processed_at timestamp(6), processed_by bigint, updated_at timestamp(6), period_code varchar(40) not null, notes TEXT, status varchar(255) not null check (status in ('OPEN','CALCULATED','APPROVED','PROCESSED','CLOSED','CANCELLED')), primary key (id), constraint uk_hr_payroll_period_code unique (period_code));
create table hr_payroll_runs (deduction_amount numeric(19,2) not null, employee_count integer not null, gross_amount numeric(19,2) not null, net_amount numeric(19,2) not null, run_number integer not null, approved_at timestamp(6), approved_by bigint, created_at timestamp(6), created_by bigint, currency varchar(8) not null, id bigserial not null, payroll_period_id bigint not null, processed_at timestamp(6), processed_by bigint, updated_at timestamp(6), status varchar(255) not null check (status in ('DRAFT','CALCULATED','APPROVED','PROCESSED','CANCELLED')), primary key (id), constraint uk_hr_payroll_run_period_number unique (payroll_period_id, run_number));
create table hr_payslips (allowances numeric(19,2) not null, basic_salary numeric(19,2) not null, bonuses numeric(19,2) not null, gross_salary numeric(19,2) not null, net_salary numeric(19,2) not null, other_deductions numeric(19,2) not null, overtime numeric(19,2) not null, pension numeric(19,2) not null, period_end_date date, period_start_date date, tax numeric(19,2) not null, total_deductions numeric(19,2) not null, created_at timestamp(6), currency varchar(8) not null, employee_id bigint not null, id bigserial not null, payroll_item_id bigint not null unique, payroll_period_id bigint not null, payroll_run_id bigint not null, payslip_number varchar(40) not null, payment_status varchar(255) not null check (payment_status in ('PENDING','PARTIAL','PAID')), primary key (id), constraint uk_hr_payslip_number unique (payslip_number));
create table hr_positions (active boolean not null, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), code varchar(40) not null, description TEXT, name varchar(255) not null, primary key (id), constraint uk_hr_position_code unique (code));
create table hr_salary_history (basic_salary numeric(19,2) not null, effective_date date not null, approved_by bigint, created_at timestamp(6), currency varchar(8) not null, employee_id bigint not null, id bigserial not null, reason TEXT, primary key (id), constraint uk_hr_salary_employee_effective unique (employee_id, effective_date));
create table internal_requisitions (total_value numeric(38,2), approved_at timestamp(6), approved_by bigint, barn_id bigint, consumed_at timestamp(6), farm_id bigint, flock_id bigint, id bigserial not null, issued_at timestamp(6), issued_by bigint, requested_at timestamp(6), requested_by bigint, updated_at timestamp(6), notes varchar(255), requisition_number varchar(255) not null unique, status varchar(255) check (status in ('DRAFT','REQUESTED','FINANCE_REVIEW','APPROVED','PARTIALLY_ISSUED','ISSUED','CONSUMED','REJECTED','CANCELLED')), primary key (id));
create table internal_stock_deliveries (delivery_date date not null, quantity numeric(14,3) not null, approved_by bigint, created_at timestamp(6), created_by bigint, deliverer_id bigint, id bigserial not null, inventory_item_id bigint not null, issued_by bigint, received_by bigint, receiver_id bigint, stock_movement_id bigint, updated_at timestamp(6), version bigint, status varchar(20) not null check (status in ('DRAFT','SUBMITTED','APPROVED','ISSUED','RECEIVED','CANCELLED')), unit varchar(20), receipt_number varchar(40) not null unique, destination_location varchar(120), source_location varchar(120), purpose varchar(200), notes TEXT, primary key (id));
create table inventory_batches (expiry_date date, is_active boolean not null, manufacturing_date date, quantity_received float(53) not null, quantity_remaining float(53) not null, quantity_reserved float(53), received_date date not null, unit_cost numeric(38,2), created_at timestamp(6), id bigserial not null, inventory_item_id bigint not null, received_by bigint, batch_number varchar(255) not null, po_reference varchar(255), shelf_location varchar(255), status varchar(255) check (status in ('AVAILABLE','RESERVED','QUARANTINED','EXPIRED','DAMAGED','DISPOSED')), storage_zone varchar(255), primary key (id), unique (inventory_item_id, batch_number));
create table inventory_counts (count_date date not null, counted_qty float(53) not null, expected_qty float(53) not null, batch_id bigint, counted_by bigint, id bigserial not null, inventory_item_id bigint not null, notes TEXT, status varchar(255), primary key (id));
create table inventory_items (avg_unit_cost numeric(38,2), current_stock float(53), is_controlled boolean, last_purchase_price numeric(38,2), lead_time_days integer, partner_price numeric(12,2), reorder_point float(53), reorder_qty float(53), reserved_stock float(53), retail_price numeric(12,2), safety_stock float(53), selling_price numeric(38,2), unit_weight_kg numeric(38,2), wholesale_price numeric(12,2), created_at timestamp(6), id bigserial not null, preferred_supplier_id bigint, supplier_id bigint, updated_at timestamp(6), allocation_type varchar(255) check (allocation_type in ('INTERNAL','EXTERNAL','HYBRID')), barcode varchar(255) unique, category varchar(255) check (category in ('FEED','DRUG','VACCINE','VITAMIN','EQUIPMENT','MATERIAL','FARM_MATERIAL','CLEANING_MATERIAL','OFFICE_SUPPLY','CONSUMABLE','EGGS','PACKAGING')), description varchar(255), item_name varchar(255) not null, rfid_tag varchar(255) unique, shelf_location varchar(255), sku varchar(255) not null unique, status varchar(255) check (status in ('ACTIVE','INACTIVE')), storage_location varchar(255), storage_zone varchar(255), subcategory varchar(255), unit varchar(255) check (unit in ('KG','SACK','BOTTLE','VIAL','PIECE','LITER','DOSE','BOX')), primary key (id));
create table invoice_items (line_total numeric(38,2) not null, quantity float(53) not null, unit_price numeric(38,2) not null, id bigserial not null, invoice_id bigint not null, account_code varchar(255) check (account_code in ('REV_POULTRY_SALES','REV_EGG_SALES','REV_PHARMACY_DRUGS','REV_PHARMACY_VACCINES','REV_PHARMACY_EQUIPMENT','REV_VET_SERVICES','REV_CONSULTING','REV_TRAINING','REV_WORKSHOP','REV_OTHER','EXP_FEED','EXP_VACCINE','EXP_DRUG','EXP_FARM_LABOR','EXP_UTILITIES','EXP_TRANSPORT','EXP_TRAINING_COSTS','EXP_CONSULTING_COSTS','EXP_MARKETING','EXP_EQUIPMENT','EXP_MAINTENANCE','EXP_ADMIN','EXP_SALARIES','COGS_POULTRY','COGS_PHARMACY','ASSET_CASH','ASSET_BANK','ASSET_RECEIVABLE','ASSET_WALLET','ASSET_INVENTORY','LIABILITY_VAT','LIABILITY_AP','LIABILITY_CREDIT','LIABILITY_SALARY_PAYABLE','LIABILITY_PAYROLL_DEDUCTIONS')), description varchar(255) not null, primary key (id));
