create table marketing_campaigns (budget numeric(38,2), conversions integer, end_date date, leads_generated integer, spent numeric(38,2), start_date date, created_at timestamp(6), id bigserial not null, channel varchar(255) check (channel in ('FACEBOOK','TELEGRAM','WEBSITE','REFERRAL','WALK_IN','GOOGLE','EMAIL','OTHER')), description varchar(255), name varchar(255) not null, status varchar(255) check (status in ('DRAFT','ACTIVE','PAUSED','COMPLETED')), primary key (id));
create table marketing_leads (converted boolean not null, campaign_id bigint, created_at timestamp(6), crm_client_id bigint, id bigserial not null, email varchar(255), full_name varchar(255), notes varchar(255), organization varchar(255), phone varchar(255), source varchar(255) check (source in ('FACEBOOK','TELEGRAM','WEBSITE','REFERRAL','WALK_IN','GOOGLE','EMAIL','OTHER')), primary key (id));
create table master_data_items (active boolean not null, sort_order integer, created_at timestamp(6), id bigserial not null, updated_at timestamp(6), item_value varchar(100) not null, label varchar(150) not null, description varchar(500), category varchar(255) not null check (category in ('BREED','DRUG_TYPE','FEED_TYPE','BARN_TYPE','EGG_GRADE','DISEASE_TYPE','VACCINE_TYPE','FLOCK_PURPOSE','ITEM_CATEGORY','MOVEMENT_REASON')), primary key (id), constraint uq_master_data_category_value unique (category, item_value));
create table material_goods_receipt_lines (expiry_date date, quantity_received numeric(14,3) not null, goods_receipt_id bigint not null, id bigserial not null, inventory_item_id bigint not null, request_line_id bigint, stock_movement_id bigint, batch_number varchar(80), condition_note varchar(80), primary key (id));
