create table material_request_lines (estimated_line_total numeric(18,2), estimated_unit_price numeric(18,4), quantity_approved numeric(14,3), quantity_issued numeric(14,3), quantity_ordered numeric(14,3), quantity_received numeric(14,3), quantity_requested numeric(14,3) not null, id bigserial not null, inventory_item_id bigint not null, last_stock_movement_id bigint, material_request_id bigint not null, unit varchar(40), notes TEXT, purpose TEXT, primary key (id));
