create table notifications (is_read boolean not null, created_at timestamp(6), id bigserial not null, related_id bigint, target_user_id bigint, message TEXT, related_module varchar(255), target_role varchar(255) check (target_role in ('ADMIN','GENERAL_MANAGER','OPERATIONS_MANAGER','SECRETARY','FINANCE','HR','FARM_MANAGER','FARM_WORKER','VETERINARIAN','INVENTORY_MANAGER','PHARMACIST','CRM_MANAGER','MARKETING_MANAGER','TRAINING_COORDINATOR','CONSULTANT','EXTENSION_WORKER','MARKETING','TRAINING_OFFICER','VETERINARY_OFFICER','STORE_KEEPER','PHARMACY_SALES','FINANCE_OFFICER')), title varchar(255) not null, type varchar(255) check (type in ('INFO','WARNING','URGENT','SYSTEM')), primary key (id));
create table pharmacy_customers (credit_limit numeric(12,2), is_active boolean not null, outstanding_balance numeric(12,2), created_at timestamp(6), id bigserial not null, updated_at timestamp(6), address TEXT, customer_code varchar(255) not null unique, customer_type varchar(255) check (customer_type in ('RETAIL','WHOLESALE','PARTNER_FARM')), email varchar(255), farm_name varchar(255), farm_type varchar(255), name varchar(255) not null, notes TEXT, phone varchar(255), primary key (id));
