create table pharmacy_sales (discount_amount numeric(10,2), subtotal numeric(10,2), tax_amount numeric(10,2), total_amount numeric(10,2), created_at timestamp(6), customer_id bigint, id bigserial not null, patient_id bigint, prescription_id bigint, sold_by bigint not null, payment_method varchar(30), customer_name varchar(255), customer_phone varchar(255), notes TEXT, payment_status varchar(255) check (payment_status in ('PAID','CREDIT','PARTIAL')), price_type varchar(255) check (price_type in ('RETAIL','WHOLESALE','PARTNER')), sale_code varchar(255) not null unique, items json, primary key (id));
create table prescription_items (duration_days integer, is_active boolean, line_total numeric(10,2), quantity_dispensed numeric(10,2), quantity_prescribed numeric(10,2), unit_price numeric(10,2), batch_id bigint, dispensed_at timestamp(6), id bigserial not null, inventory_item_id bigint not null, prescription_id bigint not null, dosage varchar(255), frequency varchar(255), label_text TEXT, primary key (id));
create table prescriptions (dispensed_expiry date, duration_days integer, prescribed_date date, quantity float(53), total_cost_at_dispense numeric(38,2), treatment_start_date date, unit_cost_at_dispense numeric(38,2), withdrawal_end_date date, withdrawal_period_days integer, approved_at timestamp(6), approved_by bigint, barn_id bigint, cancelled_at timestamp(6), client_id bigint, completed_at timestamp(6), created_at timestamp(6), created_by_vet bigint, disease_case_id bigint, dispensed_at timestamp(6), dispensed_batch_id bigint, dispensed_by bigint, farm_id bigint, flock_id bigint, id bigserial not null, inventory_item_id bigint, treatment_id bigint, updated_at timestamp(6), version bigint, administration_route varchar(255), dispensed_lot_number varchar(255), dosage_instruction varchar(255), drug_name varchar(255), frequency varchar(255), notes TEXT, prescription_number varchar(255) not null unique, prescription_type varchar(255) check (prescription_type in ('INTERNAL_FARM','EXTERNAL_CLIENT')), priority varchar(255) check (priority in ('LOW','NORMAL','HIGH','URGENT')), rejection_reason TEXT, status varchar(255) check (status in ('DRAFT','PENDING','SUBMITTED','PENDING_PHARMACY','APPROVED','DISPENSED','COMPLETED','REJECTED','CANCELLED')), unit varchar(255), primary key (id));
create table proc_goods_receipt_items (expiry_date date, manufacture_date date, received_qty float(53) not null, rejected_qty float(53), unit_cost numeric(38,2), goods_receipt_id bigint not null, id bigserial not null, inventory_item_id bigint not null, po_item_id bigint not null, stock_batch_id bigint, batch_number varchar(255), primary key (id));
create table proc_goods_receipts (receipt_date date, created_at timestamp(6), id bigserial not null, posted_at timestamp(6), purchase_order_id bigint not null, received_by bigint, supplier_id bigint not null, updated_at timestamp(6), status varchar(16) not null check (status in ('DRAFT','POSTED','CANCELLED')), grn_number varchar(32) not null unique, notes TEXT, primary key (id));
create table proc_number_sequences (next_value bigint not null, name varchar(40) not null, primary key (name));
create table proc_requisition_items (estimated_unit_price numeric(38,2), quantity_requested float(53) not null, id bigserial not null, inventory_item_id bigint not null, requisition_id bigint not null, notes TEXT, primary key (id));
create table proc_requisitions (needed_by date, approved_at timestamp(6), approved_by bigint, converted_po_id bigint, created_at timestamp(6), id bigserial not null, requested_by bigint not null, reviewed_at timestamp(6), reviewed_by bigint, updated_at timestamp(6), priority varchar(16) not null check (priority in ('LOW','NORMAL','HIGH','URGENT')), status varchar(24) not null check (status in ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','CANCELLED','CONVERTED')), requisition_number varchar(32) not null unique, justification TEXT, rejection_reason TEXT, title varchar(255) not null, primary key (id));
create table proc_supplier_invoice_items (line_total numeric(38,2), quantity float(53) not null, unit_price numeric(38,2) not null, id bigserial not null, inventory_item_id bigint, po_item_id bigint, supplier_invoice_id bigint not null, description varchar(255), primary key (id));
create table proc_supplier_invoices (due_date date, invoice_date date, paid_amount numeric(38,2), subtotal numeric(38,2), tax_amount numeric(38,2), total_amount numeric(38,2), approved_at timestamp(6), approved_by bigint, created_at timestamp(6), created_by bigint, currency varchar(8), goods_receipt_id bigint, id bigserial not null, purchase_order_id bigint, supplier_id bigint not null, updated_at timestamp(6), match_status varchar(16) not null check (match_status in ('PENDING','MATCHED','MISMATCHED')), status varchar(24) not null check (status in ('DRAFT','SUBMITTED','MATCHED','MISMATCHED','APPROVED','PARTIALLY_PAID','PAID','CANCELLED')), invoice_number varchar(32) not null unique, supplier_invoice_number varchar(64) not null, match_notes TEXT, notes TEXT, primary key (id), constraint uk_supplier_invoice_number unique (supplier_id, supplier_invoice_number));
create table proc_supplier_payments (amount numeric(38,2) not null, payment_date date not null, created_at timestamp(6), id bigserial not null, recorded_by bigint, supplier_invoice_id bigint not null, payment_method varchar(24) not null check (payment_method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), payment_number varchar(32) not null unique, notes TEXT, primary key (id));
create table purchase_order_items (line_total numeric(38,2), quantity_ordered float(53) not null, quantity_received float(53), unit_price numeric(38,2), id bigserial not null, inventory_item_id bigint not null, po_id bigint not null, notes TEXT, primary key (id));
create table purchase_orders (actual_delivery date, expected_delivery date, order_date date, subtotal numeric(38,2), tax_amount numeric(38,2), total_amount numeric(38,2), approved_at timestamp(6), approved_by bigint, created_at timestamp(6), created_by bigint, currency varchar(8), id bigserial not null, requisition_id bigint, supplier_id bigint not null, updated_at timestamp(6), status varchar(32) not null, notes TEXT, payment_terms varchar(255), po_number varchar(255) not null unique, primary key (id));
create table purchase_requisitions (requested_qty float(53), created_at timestamp(6), id bigserial not null, item_id bigint not null, requested_by bigint, status varchar(255) check (status in ('DRAFT','REQUESTED','FINANCE_REVIEW','APPROVED','PARTIALLY_ISSUED','ISSUED','CONSUMED','REJECTED','CANCELLED')), primary key (id));
create table requisition_items (quantity_approved float(53), quantity_issued float(53), quantity_requested float(53), total_cost numeric(38,2), unit_cost numeric(38,2), from_location_id bigint, id bigserial not null, inventory_item_id bigint not null, requisition_id bigint not null, primary key (id));
create table roles (id bigserial not null, name varchar(255) not null unique, permissions json not null, primary key (id));
create table silos (capacity float(53), current_level float(53), barn_id bigint not null, current_recipe_id bigint, id bigserial not null, updated_at timestamp(6), name varchar(255) not null, primary key (id));
create table stock_movements (quantity float(53) not null, total_cost numeric(38,2), unit_cost numeric(38,2), batch_id bigint, created_at timestamp(6), created_by bigint, id bigserial not null, inventory_item_id bigint not null, reference_id bigint, scanned_by bigint, from_location varchar(255), movement_type varchar(255) not null check (movement_type in ('RECEIPT','ISSUE','SALE','TRANSFER','ADJUSTMENT','RETURN','EXPIRED','DAMAGED','COUNT','INTERNAL_CONSUMPTION')), notes TEXT, reason_code varchar(255), reference_type varchar(255), to_location varchar(255), primary key (id));
create table suppliers (active boolean not null, rating integer, created_at timestamp(6), currency varchar(8), id bigserial not null, updated_at timestamp(6), supplier_code varchar(32) unique, address varchar(255), category TEXT, contact_person varchar(255), email varchar(255), name varchar(255) not null, notes TEXT, payment_terms varchar(255), phone varchar(255), tax_identifier varchar(255), primary key (id));
create table training_attendance (session_date date not null, check_in_time timestamp(6), created_at timestamp(6), id bigserial not null, recorded_by bigint, registration_id bigint not null, session_id bigint not null, notes TEXT, status varchar(255) not null check (status in ('PRESENT','ABSENT','EXCUSED')), primary key (id), constraint uk_training_attendance unique (registration_id, session_date));
create table training_certificates (issue_date date, created_at timestamp(6), id bigserial not null, issued_by bigint, program_id bigint not null, registration_id bigint not null unique, session_id bigint not null, certificate_number varchar(40) not null, verification_code varchar(48) not null, certificate_type varchar(255) not null check (certificate_type in ('COMPLETION','PARTICIPATION','ACHIEVEMENT')), participant_name varchar(255), status varchar(255) not null check (status in ('DRAFT','ISSUED','REVOKED')), primary key (id), constraint uk_training_cert_number unique (certificate_number), constraint uk_training_cert_verification unique (verification_code));
create table training_payments (amount numeric(14,2) not null, payment_date date not null, created_at timestamp(6), finance_transaction_id bigint, id bigserial not null, invoice_id bigint, recorded_by bigint, registration_id bigint not null, notes TEXT, payment_method varchar(255) not null check (payment_method in ('CASH','BANK_TRANSFER','MOBILE_MONEY','CREDIT')), primary key (id));
create table training_programs (default_capacity integer, duration_hours integer, end_date date, price numeric(14,2) not null, registration_deadline date, start_date date, created_at timestamp(6), created_by bigint, currency varchar(8) not null, id bigserial not null, updated_at timestamp(6), program_code varchar(40) not null, category varchar(255) not null check (category in ('PROFESSIONAL','AGRICULTURAL','VETERINARY','WORKSHOP','TECHNICAL','OTHER')), delivery_mode varchar(255) not null check (delivery_mode in ('ONSITE','ONLINE','HYBRID')), description TEXT, location varchar(255), objectives TEXT, status varchar(255) not null check (status in ('DRAFT','PUBLISHED','REGISTRATION_OPEN','REGISTRATION_CLOSED','IN_PROGRESS','COMPLETED','CANCELLED')), title varchar(255) not null, trainer_name varchar(255), primary key (id), constraint uk_training_program_code unique (program_code));
create table training_registrations (completed boolean not null, discount_amount numeric(14,2) not null, outstanding_amount numeric(14,2) not null, paid_amount numeric(14,2) not null, price numeric(14,2) not null, registration_date date not null, tax_amount numeric(14,2) not null, total_amount numeric(14,2) not null, client_id bigint not null, completed_at timestamp(6), completed_by bigint, created_at timestamp(6), id bigserial not null, invoice_id bigint, registered_by bigint, session_id bigint not null, updated_at timestamp(6), registration_number varchar(40) not null, job_title varchar(255), notes TEXT, organization varchar(255), participant_email varchar(255), participant_name varchar(255) not null, participant_phone varchar(255), payment_status varchar(255) not null check (payment_status in ('UNPAID','PARTIALLY_PAID','PAID')), status varchar(255) not null check (status in ('PENDING','CONFIRMED','CANCELLED','COMPLETED')), primary key (id), constraint uk_training_reg_number unique (registration_number), constraint uk_training_reg_session_client unique (session_id, client_id));
create table training_sessions (capacity integer not null, confirmed_count integer not null, end_date date, start_date date not null, created_at timestamp(6), id bigserial not null, program_id bigint not null, updated_at timestamp(6), session_code varchar(40) not null, notes TEXT, status varchar(255) not null check (status in ('DRAFT','SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')), trainer_name varchar(255), venue varchar(255), primary key (id), constraint uk_training_session_code unique (session_code));
create table treatment_records (end_date date, quantity float(53), start_date date, created_at timestamp(6), disease_case_id bigint, farm_id bigint, flock_id bigint, id bigserial not null, inventory_item_id bigint, updated_at timestamp(6), vet_officer bigint, dosage varchar(255), drug_name varchar(255), duration varchar(255), outcome varchar(255), route varchar(255), status varchar(255) check (status in ('ACTIVE','COMPLETED','CANCELLED')), treatment_type varchar(255), primary key (id));
create table user_farm_access (farm_id bigint, user_id bigint not null);
create table users (created_at timestamp(6), id bigserial not null, updated_at timestamp(6), email varchar(255) not null unique, full_name varchar(255) not null, password varchar(255) not null, phone varchar(255), role varchar(255) not null check (role in ('ADMIN','GENERAL_MANAGER','OPERATIONS_MANAGER','SECRETARY','FINANCE','HR','FARM_MANAGER','FARM_WORKER','VETERINARIAN','INVENTORY_MANAGER','PHARMACIST','CRM_MANAGER','MARKETING_MANAGER','TRAINING_COORDINATOR','CONSULTANT','EXTENSION_WORKER','MARKETING','TRAINING_OFFICER','VETERINARY_OFFICER','STORE_KEEPER','PHARMACY_SALES','FINANCE_OFFICER')), status varchar(255) not null check (status in ('ACTIVE','INACTIVE')), primary key (id));
create table vaccination_schedules (actual_date date, next_dose_date date, scheduled_date date, created_at timestamp(6), farm_id bigint, flock_id bigint, given_by bigint, id bigserial not null, updated_at timestamp(6), batch_number varchar(255), disease_protected_against varchar(255), dosage varchar(255), remarks varchar(255), responsible_person varchar(255), route varchar(255), status varchar(255) check (status in ('SCHEDULED','COMPLETED','MISSED')), vaccine_name varchar(255), vaccine_type varchar(255), primary key (id));
create table vaccination_templates (day_age integer, id bigserial not null, breed varchar(255), disease_protected_against varchar(255), dosage varchar(255), instructions TEXT, name varchar(255), route varchar(255), vaccine_name varchar(255), primary key (id));
create table veterinary_attachments (created_at timestamp(6), entity_id bigint not null, file_size bigint, id bigserial not null, uploaded_by bigint, content_type varchar(255), entity_type varchar(255) not null, file_name varchar(255), file_path varchar(255), primary key (id));
create table wallet_transactions (amount numeric(38,2) not null, created_at timestamp(6), id bigserial not null, reference_id bigint, wallet_id bigint not null, description varchar(255), reference_type varchar(255), type varchar(255) not null, primary key (id));
